head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50202";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Excel();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt50202.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_2_onsubmit
 * @description form_2 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_2_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50202.form_2_onsubmit' }); }
};

/**
 * @method
 * @name slc_targetFormUpclssCd_onchange
 * @description slc_targetFormUpclssCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_targetFormUpclssCd_onchange = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50202.slc_targetFormUpclssCd_onchange' }); }
};

/**
 * @method
 * @name ipt_keyword_onkeyup
 * @description ipt_keyword 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_keyword_onkeyup = async function(e){
    try {
        await scwin.onEnter()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50202.ipt_keyword_onkeyup' }); }
};

/**
 * @method
 * @name img_43_onclick
 * @description img_43 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_43_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50202.img_43_onclick' }); }
};

/**
 * @method
 * @name img_64_onclick
 * @description 「[없음]」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_64_onclick = async function(e){
    try {
        await scwin.excel()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50202.img_64_onclick' }); }
};

/**
 * @method
 * @name img_66_onclick
 * @description img_66 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_66_onclick = async function(e){
    try {
        await scwin.popInsert()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50202.img_66_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Excel
 * @description Excel 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Excel = async function () {
    const sbmOptions = {
        id: "tx_fn_Excel",
        method: "post",
        action: "/filing/reasonClass.do",
        ref: "dma_ExcelReq",
        target: "dlt_formUpclasses=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_List_xhr
 * @description List xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_List_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr", unresolved: "action:self_submit:tx_fn_List_xhr" };
};

/**
 * @method
 * @name tx_fn_Delete_xhr
 * @description Delete xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Delete_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Delete_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Delete_xhr", unresolved: "action:self_submit:tx_fn_Delete_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    $c.util.getComponent('dma_ExcelReq').set('pageIndex', 1);
    await scwin.list();
};

/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    $c.util.getComponent('dma_ExcelReq').set('formUpclssCd', $c.util.getComponent('slc_targetFormUpclssCd').getValue());
    scwin.form_listForm.action = "/filing/reasonClass.do";
    $c.util.getComponent('dma_ExcelReq').set('method', "findReasonClasses");
    await scwin.tx_fn_List_xhr();
};

/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} responseText responseText
 * @returns {void}
 * @hidden N
 */
scwin.onCompleteResponse = function (responseText) {
    ($c.util.getComponent('listDiv') && $c.util.getComponent('listDiv').setValue) ? $c.util.getComponent('listDiv').setValue(responseText) : (($c.util.getComponent('listDiv') && $c.util.getComponent('listDiv').setText) ? $c.util.getComponent('listDiv').setText(responseText) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'listDiv'), void (responseText)));
};

/**
 * @method
 * @name popInsert
 * @description pop Insert 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popInsert = async function () {
    const _url = "/filing/reasonClass.do?method=prepareUpdateReasonClass&mode=create";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "reasonClassPop", popupName: "reasonClassPop" }, {});
};

/**
 * @method
 * @name popModify
 * @description pop Modify 처리
 * @param {String} formUpclssCd formUpclssCd
 * @param {String} rsnClssCd rsnClssCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popModify = async function (formUpclssCd, rsnClssCd) {
    const _url = "/filing/reasonClass.do?method=prepareUpdateReasonClass" + "&formUpclssCd=" + formUpclssCd + "&rsnClssCd=" + rsnClssCd + "&mode=update";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "reasonClassPop", popupName: "reasonClassPop" }, {});
};

/**
 * @method
 * @name deleteExcelReq
 * @description delete Excel Req 처리
 * @param {String} formUpclssCd formUpclssCd
 * @param {String} rsnClssCd rsnClssCd
 * @param {String} disclsRsnClssNm disclsRsnClssNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteExcelReq = async function (formUpclssCd, rsnClssCd, disclsRsnClssNm) {
    const _confirm = await $c.win.confirm("사유분류 '" + disclsRsnClssNm + "'를\n삭제하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.util.getComponent('dma_ExcelReq').set('formUpclssCd', formUpclssCd);
    $c.util.getComponent('dma_ExcelReq').set('rsnClssCd', rsnClssCd);
    scwin.form_listForm.action = "/filing/reasonClass.do";
    $c.util.getComponent('dma_ExcelReq').set('method', "deleteReasonClass");
    await scwin.tx_fn_Delete_xhr();
};

/**
 * @method
 * @name onEnter
 * @description on Enter 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onEnter = async function () {
    if (event.keyCode === 13) {
        await scwin.search();
    }
};

/**
 * @method
 * @name excel
 * @description excel 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excel = async function () {
    scwin.form_listForm.action = "/filing/reasonClass.do";
    $c.util.getComponent('dma_ExcelReq').set('method', "downloadReasonClassList");
    scwin.form_listForm.target = "hiddenFrame";
    await scwin.tx_fn_Excel();
};
